// ============================================================================
// Core Data Structures
// ============================================================================

struct InterruptFrame
  // 기본 레지스터 상태
  rax: number
  rcx: number
  rdx: number
  rsi: number
  rdi: number
  r8: number
  r9: number
  r10: number
  r11: number

