  assert(decision.recommendedLayer == "cpu", "Compute-intensive should recommend 'cpu'")
  assert(decision.priority == 2, "CPU priority should be 2")

fn testLayerSwitchROI()
  // 무관용: Layer 전환 ROI > 1.5x (switching cost vs gain)

  let currentLayer = "algorithm"
  let recommendation = {
    "recommendedLayer": "cache",
    "priority": 4,
    "estimatedImprovement": 0.45,
    "confidence": 0.88,
