    "recommendedLayer": "cache",
    "priority": 4,
    "estimatedImprovement": 0.45,
    "confidence": 0.88,
    "reason": "High memory access"
  }
  let switchingCost = 10  // µs

  let shouldSwitch = shouldSwitchLayer(currentLayer, recommendation, switchingCost)
  assert(shouldSwitch == true, "ROI > 1.5x should trigger layer switch")

fn testMultiLayerOrchestration()
  // 무관용: Multiple layers 동시 최적화 (no interference)

  let decisions = [
    {
      "recommendedLayer": "cache",
      "priority": 4,
      "estimatedImprovement": 0.45,
      "confidence": 0.88,
