      "reason": "Network latency"
    }
  ]

  let profile = buildWorkloadProfile(0.8, 1500000, 200, 0.6, 0.04)
  let orchestration = orchestrateMultipleLayers(profile, decisions)

  assert(orchestration.length() > 0, "Orchestration should return non-empty list")
  assert(orchestration.length() <= 2, "Should apply max 2 optimizations (avoid interference)")

