  let recentMetrics = [
    { "latencyUs": 200, "throughputOpsPerUs": 1.0, "cacheHitRate": 0.95, "energyPerOp": 35.0, "stability": 0.99, "converged": false },
    { "latencyUs": 201, "throughputOpsPerUs": 1.0, "cacheHitRate": 0.95, "energyPerOp": 35.0, "stability": 0.99, "converged": false },
