fn testTimeoutCalculation()
  // 무관용: Timeout 정확 계산 (< 100µs 목표)

  let timeout = calculateOptimalTimeout(32, 2, 100, 1000)

  assert(timeout >= 10, "Timeout should be at least 10µs")
  assert(timeout <= 100, "Timeout should not exceed 100µs")

fn testProtocolSelection()
